                    hotspot.feedback = new Feedback_1.Feedback(this.m_htmlDOM.createAutoGrowTextElement(text, pos, styleData, Enums_1.ResizeFactor.ELEMENT3D));
                    hotspot.feedback.setposition(new THREE.Vector3(((hotspot.feedback.domElement.clientWidth + Enums_1.ResizeHandleGeometry.width) / (2 * Enums_1.ResizeFactor.ELEMENT3D)) + ((hotspot.hotspotSize.width * hotspot.group.scale.x) / (2 * 2)), ((hotspot.feedback.domElement.clientHeight + Enums_1.ResizeHandleGeometry.height) / (2 * Enums_1.ResizeFactor.ELEMENT3D)) + ((hotspot.hotspotSize.height * hotspot.group.scale.y) / (2 * 2)), 0));
                    hotspot.setfbDims(hotspot.feedback.domElement.clientWidth / Enums_1.ResizeFactor.ELEMENT3D, hotspot.feedback.domElement.clientHeight / Enums_1.ResizeFactor.ELEMENT3D);
                    hotspot.updateFeedbackGroup(false);
